initJs:
function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = 'accuracy';
  let sortDirection = 'desc';
  let chartPeriod = 'daily';

  // 店舗選択の初期化
  function initStoreFilter() {
    const storeFilter = container.querySelector('#store-filter');
    const stores = tables[1]?.records || [];
    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = store.店舗名;
      storeFilter.appendChild(option);
    });
  }

  // 精度データの計算
  function calculateAccuracyMetrics(predictions) {
    if (!predictions.length) return { avgAccuracy: 0, mape: 0, rmse: 0, count: 0 };

    let totalAccuracy = 0;
    let totalMape = 0;
    let totalRmse = 0;
    let validCount = 0;

    predictions.forEach(pred => {
      const predicted = pred.予測数量 || 0;
      const actual = pred.実績数量 || 0;

      if (actual > 0) {
        const accuracy = Math.max(0, 100 - Math.abs((predicted - actual) / actual * 100));
        const ape = Math.abs((predicted - actual) / actual * 100);
        const se = Math.pow(predicted - actual, 2);

        totalAccuracy += accuracy;
        totalMape += ape;
        totalRmse += se;
        validCount++;
      }
    });

    return {
      avgAccuracy: validCount > 0 ? (totalAccuracy / validCount).toFixed(1) : 0,
      mape: validCount > 0 ? (totalMape / validCount).toFixed(2) : 0,
      rmse: validCount > 0 ? Math.sqrt(totalRmse / validCount).toFixed(2) : 0,
      count: validCount
    };
  }

  // サマリーカードの更新
  function updateSummaryCards(data) {
    const metrics = calculateAccuracyMetrics(data);

    container.querySelector('#avg-accuracy').textContent = metrics.avgAccuracy + '%';
    container.querySelector('#mape-value').textContent = metrics.mape + '%';
    container.querySelector('#rmse-value').textContent = metrics.rmse;
    container.querySelector('#data-count').textContent = metrics.count + '件';

    // アラート表示判定
    const alertPanel = container.querySelector('#alert-panel');
    const alertContent = container.querySelector('#alert-content');

    if (parseFloat(metrics.avgAccuracy) < 80) {
      alertContent.innerHTML = `
        <p>予測精度が閾値(80%)を下回りました</p>
        <p>現在の平均精度: ${metrics.avgAccuracy}% (${new Date().toLocaleString()})</p>
      `;
      alertPanel.style.display = 'block';
    } else {
      alertPanel.style.display = 'none';
    }
  }

  // 予測精度推移グラフの描画
  function drawAccuracyChart(data) {
    const canvas = container.querySelector('#accuracy-chart');
    const ctx = canvas.getContext('2d');

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = { top: 20, right: 20, bottom: 40, left: 60 };

    // 背景クリア
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, width, height);

    if (!data.length) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', width / 2, height / 2);
      return;
    }

    // データの期間別集計
    const groupedData = {};
    data.forEach(item => {
      const date = new Date(item.予測対象日);
      let key;

      if (chartPeriod === 'daily') {
        key = date.toISOString().split('T')[0];
      } else if (chartPeriod === 'weekly') {
        const weekStart = new Date(date);
        weekStart.setDate(date.getDate() - date.getDay());
        key = weekStart.toISOString().split('T')[0];
      } else {
        key = date.getFullYear() + '-' + String(date.getMonth() + 1).padStart(2, '0');
      }

      if (!groupedData[key]) {
        groupedData[key] = { predictions: [], date: key };
      }
      groupedData[key].predictions.push(item);
    });

    const chartData = Object.values(groupedData).map(group => {
      const metrics = calculateAccuracyMetrics(group.predictions);
      return {
        date: group.date,
        accuracy: parseFloat(metrics.avgAccuracy)
      };
    }).sort((a, b) => a.date.localeCompare(b.date));

    if (!chartData.length) return;

    // グラフ描画エリア
    const chartWidth = width - padding.left - padding.right;
    const chartHeight = height - padding.top - padding.bottom;

    // Y軸（0-100%）
    ctx.strokeStyle = '#3a4a5c';
    ctx.lineWidth = 1;

    for (let i = 0; i <= 10; i++) {
      const y = padding.top + (chartHeight * i / 10);
      ctx.beginPath();
      ctx.moveTo(padding.left, y);
      ctx.lineTo(width - padding.right, y);
      ctx.stroke();

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px Arial';
      ctx.textAlign = 'right';
      ctx.fillText((100 - i * 10) + '%', padding.left - 5, y + 4);
    }

    // X軸
    const xStep = chartWidth / (chartData.length - 1 || 1);
    chartData.forEach((item, index) => {
      const x = padding.left + (index * xStep);

      ctx.strokeStyle = '#3a4a5c';
      ctx.beginPath();
      ctx.moveTo(x, padding.top);
      ctx.lineTo(x, height - padding.bottom);
      ctx.stroke();

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px Arial';
      ctx.textAlign = 'center';
      const label = chartPeriod === 'monthly' ? item.date : item.date.split('-').slice(1).join('/');
      ctx.fillText(label, x, height - padding.bottom + 15);
    });

    // 精度ライン描画
    ctx.strokeStyle = '#4fc3f7';
    ctx.lineWidth = 2;
    ctx.beginPath();

    chartData.forEach((item, index) => {
      const x = padding.left + (index * xStep);
      const y = padding.top + (chartHeight * (100 - item.accuracy) / 100);

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // データポイント
    chartData.forEach((item, index) => {
      const x = padding.left + (index * xStep);
      const y = padding.top + (chartHeight * (100 - item.accuracy) / 100);

      ctx.fillStyle = '#4fc3f7';
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, 2 * Math.PI);
      ctx.fill();
    });
  }

  // 予測vs実績比較チャートの描画
  function drawComparisonChart(data) {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = { top: 20, right: 20, bottom: 40, left: 60 };

    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, width, height);

    if (!data.length) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', width / 2, height / 2);
      return;
    }

    const chartData = data.filter(item => item.実績数量 != null).slice(0, 30);
    if (!chartData.length) return;

    const maxValue = Math.max(...chartData.map(item => Math.max(item.予測数量 || 0, item.実績数量 || 0)));
    const chartWidth = width - padding.left - padding.right;
    const chartHeight = height - padding.top - padding.bottom;

    // Y軸
    ctx.strokeStyle = '#3a4a5c';
    ctx.lineWidth = 1;

    for (let i = 0; i <= 5; i++) {
      const y = padding.top + (chartHeight * i / 5);
      ctx.beginPath();
      ctx.moveTo(padding.left, y);
      ctx.lineTo(width - padding.right, y);
      ctx.stroke();

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px Arial';
      ctx.textAlign = 'right';
      ctx.fillText(Math.round(maxValue * (5 - i) / 5), padding.left - 5, y + 4);
    }

    // X軸とデータ描画
    const xStep = chartWidth / (chartData.length - 1 || 1);

    // 予測値ライン
    ctx.strokeStyle = '#ff9800';
    ctx.lineWidth = 2;
    ctx.beginPath();
    chartData.forEach((item, index) => {
      const x = padding.left + (index * xStep);
      const y = padding.top + (chartHeight * (maxValue - (item.予測数量 || 0)) / maxValue);
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 実績値ライン
    ctx.strokeStyle = '#4caf50';
    ctx.lineWidth = 2;
    ctx.beginPath();
    chartData.forEach((item, index) => {
      const x = padding.left + (index * xStep);
      const y = padding.top + (chartHeight * (maxValue - (item.実績数量 || 0)) / maxValue);
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#ff9800';
    ctx.fillRect(width - 150, 20, 15, 15);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px Arial';
    ctx.textAlign = 'left';
    ctx.fillText('予測値', width - 130, 32);

    ctx.fillStyle = '#4caf50';
    ctx.fillRect(width - 150, 40, 15, 15);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('実績値', width - 130, 52);
  }

  // ランキングテーブルの描画
  function renderRankingTable(data) {
    const tbody = container.querySelector('#ranking-tbody');

    if (!data.length) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    // 店舗・商品別に集計
    const aggregated = {};
    data.forEach(item => {
      const key = `${item.店舗ID}_${item.商品ID}`;
      if (!aggregated[key]) {
        aggregated[key] = {
          store_id: item.店舗ID,
          product_id: item.商品ID,
          predictions: []
        };
      }
      aggregated[key].predictions.push(item);
    });

    const rankingData = Object.values(aggregated).map(group => {
      const metrics = calculateAccuracyMetrics(group.predictions);
      const store = tables[1]?.records?.find(s => s.店舗ID === group.store_id);
      const product = tables[2]?.records?.find(p => p.商品ID === group.product_id);

      return {
        store_name: store?.店舗名 || '不明',
        product_name: product?.商品名 || '不明',
        category: product?.商品カテゴリID || '不明',
        accuracy: parseFloat(metrics.avgAccuracy),
        mape: parseFloat(metrics.mape),
        rmse: parseFloat(metrics.rmse),
        prediction_count: group.predictions.length
      };
    });

    // ソート
    rankingData.sort((a, b) => {
      const aVal = a[sortColumn];
      const bVal = b[sortColumn];
      const multiplier = sortDirection === 'asc' ? 1 : -1;
      return (aVal > bVal ? 1 : -1) * multiplier;
    });

    tbody.innerHTML = rankingData.map((item, index) => {
      const rank = index + 1;
      const statusClass = item.accuracy >= 90 ? 'excellent' : item.accuracy >= 80 ? 'good' : item.accuracy >= 70 ? 'fair' : 'poor';
      const statusText = item.accuracy >= 90 ? '優秀' : item.accuracy >= 80 ? '良好' : item.accuracy >= 70 ? '普通' : '要改善';
      const statusColor = item.accuracy >= 90 ? '#4caf50' : item.accuracy >= 80 ? '#2196f3' : item.accuracy >= 70 ? '#ff9800' : '#f44336';

      return `
        <tr>
          <td>${rank}</td>
          <td>${item.store_name}</td>
          <td>${item.product_name}</td>
          <td>${item.category}</td>
          <td style="font-weight: bold;">${item.accuracy.toFixed(1)}%</td>
          <td>${item.mape.toFixed(2)}%</td>
          <td>${item.rmse.toFixed(2)}</td>
          <td>${item.prediction_count}</td>
          <td><span style="color: ${statusColor}; font-weight: bold;">${statusText}</span></td>
        </tr>
      `;
    }).join('');
  }

  // データのフィルタリング
  function filterData() {
    const period = parseInt(container.querySelector('#period-filter').value);
    const storeId = container.querySelector('#store-filter').value;
    const category = container.querySelector('#category-filter').value;
    const accuracyThreshold = container.querySelector('#accuracy-filter').value;

    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - period);

    let filtered = currentData.filter(item => {
      const itemDate = new Date(item.予測対象日);
      return itemDate >= cutoffDate;
    });

    if (storeId) {
      filtered = filtered.filter(item => item.店舗ID === storeId);
    }

    if (category) {
      const products = tables[2]?.records?.filter(p => p.商品カテゴリID === category) || [];
      const productIds = products.map(p => p.商品ID);
      filtered = filtered.filter(item => productIds.includes(item.商品ID));
    }

    if (accuracyThreshold) {
      filtered = filtered.filter(item => {
        if (!item.実績数量 || item.実績数量 === 0) return false;
        const accuracy = Math.max(0, 100 - Math.abs((item.予測数量 - item.実績数量) / item.実績数量 * 100));
        return accuracy >= parseFloat(accuracyThreshold);
      });
    }

    return filtered;
  }

  // 画面更新
  function updateScreen() {
    const filteredData = filterData();
    updateSummaryCards(filteredData);
    drawAccuracyChart(filteredData);
    drawComparisonChart(filteredData);
    renderRankingTable(filteredData);
  }

  // 初期化
  initStoreFilter();

  // 初期データ読み込み
  window.aivicApi.list(4).then(rows => {
    if (rows) {
      currentData = rows;
      updateScreen();
    }
  });

  // イベントリスナー
  container.querySelector('#btn-apply-filter').addEventListener('click', updateScreen);
  container.querySelector('#btn-refresh').addEventListener('click', () => {
    window.aivicApi.list(4).then(rows => {
      if (rows) {
        currentData = rows;
        updateScreen();
      }
    });
  });

  // チャート期間切り替え
  container.addEventListener('click', e => {
    const periodBtn = e.target.closest('.chart-period-btn');
    if (periodBtn) {
      container.querySelectorAll('.chart-period-btn').forEach(btn => btn.classList.remove('active'));
      periodBtn.classList.add('active');
      chartPeriod = periodBtn.dataset.period;
      const filteredData = filterData();
      drawAccuracyChart(filteredData);
    }
  });

  // テーブルソート
  container.addEventListener('click', e => {
    const sortBtn = e.target.closest('.sortable');
    if (sortBtn) {
      const column = sortBtn.dataset.sort;
      if (sortColumn === column) {
        sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
      } else {
        sortColumn = column;
        sortDirection = 'desc';
      }

      // ソート表示更新
      container.querySelectorAll('.sortable').forEach(th => {
        th.style.background = 'var(--bg-card)';
      });
      sortBtn.style.background = 'var(--primary)';

      const filteredData = filterData();
      renderRankingTable(filteredData);
    }
  });

  // 詳細分析ボタン
  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1778591822586'); // 相関分析・比較分析画面
  });

  // レポート出力ボタン
  container.querySelector('#btn-export-report').addEventListener('click', () => {
    try {
      const filteredData = filterData();
      const metrics = calculateAccuracyMetrics(filteredData);

      const reportData = [
        ['予測精度監視レポート', '', '', '', '', ''],
        ['出力日時', new Date().toLocaleString(), '', '', '', ''],
        ['', '', '', '', '', ''],
        ['サマリー', '', '', '', '', ''],
        ['平均予測精度', metrics.avgAccuracy + '%', '', '', '', ''],
        ['MAPE', metrics.mape + '%', '', '', '', ''],
        ['RMSE', metrics.rmse, '', '', '', ''],
        ['対象データ数', metrics.count + '件', '', '', '', ''],
        ['', '', '', '', '', ''],
        ['詳細データ', '', '', '', '', ''],
        ['店舗名', '商品名', 'カテゴリ', '予測精度', 'MAPE', 'RMSE']
      ];

      // ランキングデータを追加
      const aggregated = {};
      filteredData.forEach(item => {
        const key = `${item.店舗ID}_${item.商品ID}`;
        if (!aggregated[key]) {
          aggregated[key] = {
            store_id: item.店舗ID,
            product_id: item.商品ID,
            predictions: []
          };
        }
        aggregated[key].predictions.push(item);
      });

      Object.values(aggregated).forEach(group => {
        const groupMetrics = calculateAccuracyMetrics(group.predictions);
        const store = tables[1]?.records?.find(s => s.店舗ID === group.store_id);
        const product = tables[2]?.records?.find(p => p.商品ID === group.product_id);

        reportData.push([
          store?.店舗名 || '不明',
          product?.商品名 || '不明',
          product?.商品カテゴリID || '不明',
          groupMetrics.avgAccuracy + '%',
          groupMetrics.mape + '%',
          groupMetrics.rmse
        ]);
      });

      const csvContent = '\uFEFF' + reportData.map(row => 
        row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
      ).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `予測精度監視レポート_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      alert('レポート出力に失敗しました: ' + error.message);
    }
  });
}
